function search(nums: number[], target: number): number {
  let lo = 0;
  let hi = nums.length - 1;

  while (lo <= hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (nums[mid] === target) return mid;

    // Хотя бы одна из половин [lo, mid] или [mid, hi] отсортирована
    if (nums[lo] <= nums[mid]) {
      // Левая половина отсортирована: проверяем, попадает ли target в её диапазон
      if (nums[lo] <= target && target < nums[mid]) {
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    } else {
      // Правая половина отсортирована
      if (nums[mid] < target && target <= nums[hi]) {
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
  }

  return -1;
}

// Время: O(log n)
// Память: O(1)
